import type { DesignToken, ThemedTokens } from "./swift.ts";

const GENERATED_HEADER = [
  "/* Generated by @repo/design-tokens — do not edit. */",
  "/* Source: packages/design-tokens/tokens/** */",
  "",
].join("\n");

const SAFARI_SYSTEM_FONTS: Readonly<Record<string, string>> = {
  largeTitle: "-apple-system-title0",
  headline: "-apple-system-headline",
  subheadline: "-apple-system-subheadline",
  body: "-apple-system-body",
  footnote: "-apple-system-footnote",
};

const kebab = (segment: string): string =>
  segment.replaceAll(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`);

const variableName = (path: readonly string[]): string => `--${path.map(kebab).join("-")}`;

const textStyleDeclarations = ({ path, value }: DesignToken): readonly string[] => {
  if (
    typeof value !== "object" ||
    value === null ||
    !("textStyle" in value) ||
    typeof value.textStyle !== "string"
  ) {
    throw new Error(`Token "${path.join(".")}" is not an iOS text style value.`);
  }
  const font = SAFARI_SYSTEM_FONTS[value.textStyle];
  if (font === undefined) {
    throw new Error(
      `Token "${path.join(".")}" uses the iOS text style "${value.textStyle}", which has no Safari system font.`,
    );
  }
  const weight =
    "fontWeight" in value ? [`${variableName(path)}-weight: ${String(value.fontWeight)};`] : [];
  return [`${variableName(path)}-font: ${font};`, ...weight];
};

const declarations = (token: DesignToken): readonly string[] =>
  token.$type === "iosTextStyle"
    ? textStyleDeclarations(token)
    : [`${variableName(token.path)}: ${String(token.value)};`];

const block = (tokens: readonly DesignToken[], indent: string): readonly string[] =>
  tokens.flatMap(declarations).map((line) => `${indent}${line}`);

export const formatCssVariables = ({
  themes,
  shared,
}: {
  themes: ThemedTokens;
  shared: readonly DesignToken[];
}): string =>
  [
    GENERATED_HEADER,
    ":root {",
    ...block([...themes.light, ...shared], "  "),
    "}",
    "",
    "@media (prefers-color-scheme: dark) {",
    "  :root {",
    ...block(themes.dark, "    "),
    "  }",
    "}",
    "",
  ].join("\n");
